    {
        "ObjectType":"Table",
        "Action":"Include",
        "ExpressionType":"Exact",
        "Expression":"table1"
      }
    ],
    "TransformationRuleNames":[
      {
        "RuleName":"my_database_rename_rule",
        "RuleActionType":"Rename",
